import {browserAPI,mediaURL as webMediaURL} from './browser.js';
import {uid,clone,splitScript,moveItem,timecode,durationOf,cutList} from './domain.js';

const api=window.filmdock||browserAPI;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',script:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',assets:'M12 3 3 8l9 5 9-5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5',video:'M4 5h12v14H4zM16 10l5-3v10l-5-3',cut:'M4 4h16v16H4zM9 4v16M4 9h5M4 15h5M13 10l4 2-4 2z',plug:'M8 3v5M16 3v5M5 8h14v3a7 7 0 0 1-14 0V8zM12 18v4',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',x:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',play:'m8 4 12 8-12 8V4z',pause:'M7 4v16M17 4v16',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3z',more:'M5 12h.01M12 12h.01M19 12h.01',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',folder:'M3 6h7l2 2h9v12H3V6z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',undo:'M3 10h7M3 10V3m0 7c4-8 17-6 17 3a7 7 0 0 1-10 7',trash:'M4 7h16M9 3h6M6 7l1 14h10l1-14M10 11v6M14 11v6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',link:'m9 15 6-6M8 17l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 10a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',film:'M4 3h16v18H4zM8 3v18M16 3v18M4 8h4M4 16h4M16 8h4M16 16h4',min:'M5 12h14',max:'M5 5h14v14H5z',sound:'M4 9h4l5-4v14l-5-4H4zM16 8q6 4 0 8',copy:'M8 8h12v13H8zM4 16V3h12'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const button=(label,action,extra='',cls='btn')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const media=id=>S.project.media.find(m=>m.id===id);
const url=m=>m?(S.desktop?`filmdock://media/${encodeURIComponent(m.id)}`:webMediaURL(m)):'';
const shot=id=>S.project.shots.find(s=>s.id===id);
const selected=()=>shot(S.shotId)||S.project.shots[0];
const routes=[['script','script','剧本工作室','01'],['assets','assets','资产库','02'],['board','grid','分镜画板','03'],['media','video','视频素材','04'],['edit','cut','粗剪台','05']];
const statusLabel={draft:'待制作',ready:'关键帧就绪',adopted:'已采用',queued:'排队中',running:'生成中',submitting:'提交中',succeeded:'已完成',failed:'失败',submission_unknown:'提交待确认',paused:'已暂停',downloading:'下载中',download_failed:'下载失败'};
const S={project:null,connections:[],route:'board',shotId:null,assetType:'all',mediaKind:'all',view:'grid',search:'',desktop:!!window.filmdock,modal:null,editConn:null,ffmpegPath:'ffmpeg',secretPersistent:false,clipId:null,playing:false,undo:[],redo:[],saveTimer:null,drag:null,rendering:false,renderProgress:0,inspector:true};
function toast(text,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.innerHTML=icon(error?'info':'check')+`<span>${esc(text)}</span>`;$('#toasts').append(n);while($('#toasts').children.length>2)$('#toasts').firstElementChild.remove();setTimeout(()=>n.remove(),3200);}
function saved(label,kind=''){const e=$('#save-indicator');if(e){e.innerHTML=`<i class="dot ${kind}"></i>${label}`;}}
function changed(){S.project.updatedAt=new Date().toISOString();saved('保存中','amber');clearTimeout(S.saveTimer);S.saveTimer=setTimeout(()=>flush().catch(e=>toast(e.message,true)),450);}
async function flush(){clearTimeout(S.saveTimer);try{await api.saveProject(clone(S.project));saved('已保存到本机');}catch(e){saved('保存失败','amber');throw e;}}
function selectOptions(values,value){return values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');}
function field(label,key,value,{area=false,options=null,type='text',extra='',scope='shot'}={}){return`<label class="field"><span>${label}</span>${options?`<select data-bind="${scope}.${key}">${selectOptions(options,value)}</select>`:area?`<textarea data-bind="${scope}.${key}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" data-bind="${scope}.${key}" value="${esc(value)}" ${extra}>`}</label>`;}
function blank(title,body,action,label){return`<div class="empty">${icon('film',38)}<h3>${title}</h3><p>${body}</p>${action?button(label,action,'','btn primary'):''}</div>`;}
function sidebar(){const p=S.project,adopted=p.shots.filter(s=>s.videoId).length;return`<aside class="sidebar"><div class="brand"><div class="brand-mark"><i></i><i></i><i></i><i></i></div><b>FilmDock<span>STUDIO</span></b><small>DEMO</small></div><button class="project-switch" data-action="project-menu"><span class="project-icon">${icon('film',21)}</span><span><strong>${esc(p.title)}</strong><small>${p.ratio} · ${p.fps} FPS</small></span>${icon('down',15)}</button><div class="nav-label">制作工作区 <span>WORKSPACE</span></div><nav>${routes.map(([id,ic,label,n])=>`<button class="nav-item ${S.route===id?'active':''}" data-action="route" data-route="${id}">${icon(ic)}<span>${label}</span><small>${n}</small></button>`).join('')}</nav><div class="sidebar-spacer"></div><div class="project-progress"><span>制作进度 <b>${p.shots.length?Math.round(adopted/p.shots.length*100):0}%</b></span><div class="progress-track"><i style="width:${p.shots.length?adopted/p.shots.length*100:0}%"></i></div><p>${adopted} / ${p.shots.length} 个镜头已采用视频</p></div><button class="nav-item connection-nav ${S.route==='connections'?'active':''}" data-action="route" data-route="connections">${icon('plug')}<span>连接与模型</span><small>${S.connections.length||'＋'}</small></button><div class="sidebar-footer"><span class="avatar">L</span><span>我的创作空间<small>本地优先 · 自由连接</small></span><i class="online-dot"></i></div></aside>`;}
function topbar(){const title=S.route==='connections'?'连接与模型':routes.find(r=>r[0]===S.route)?.[2];return`<div class="titlebar"><span>${icon('film',12)} FilmDock <span class="titlebar-sub">/ 创作工作台</span></span><div class="window-controls">${['min','max','x'].map((ic,i)=>`<button aria-label="${['最小化','最大化','关闭'][i]}" data-action="window" data-window="${['minimize','maximize','close'][i]}">${icon(ic,13)}</button>`).join('')}</div></div><header class="topbar"><div class="breadcrumbs"><span>我的项目</span>${icon('chevron',12)}<b>${esc(S.project.title)}</b>${icon('chevron',12)}<span>${title}</span></div><div class="top-actions"><span id="save-indicator"><i class="dot"></i>已保存到本机</span><button class="btn subtle" data-action="tasks">${icon('clock',15)}任务中心${S.project.tasks.some(t=>['running','submitting','downloading'].includes(t.status))?'<i class="busy-dot"></i>':''}</button><button class="btn small primary" data-action="handoff">${icon('download',15)}导出交接包</button></div></header>`;}
function heading(kicker,title,subtitle,actions=''){return`<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function art(m,cls='',fallback='grid'){return m?`<img class="${cls}" src="${esc(url(m))}" alt="${esc(m.name)}" draggable="false">`:`<div class="art-placeholder ${cls}">${icon(fallback,28)}<span>等待你的第一帧</span></div>`;}
function board(){const p=S.project;const shots=p.shots.filter(s=>(s.title+s.description+s.code).toLowerCase().includes(S.search.toLowerCase()));return`<div class="workspace ${S.inspector?'with-inspector':''}"><section class="main-content">${heading('STORYBOARD / 分镜与关键帧','分镜画板',`${p.shots.length} 个镜头 <i>·</i> ${timecode(p.shots.reduce((n,s)=>n+s.duration,0),p.fps).slice(0,5)} 计划时长 <i>·</i> ${p.ratio}`,button(icon('plus',16)+'添加镜头','add-shot','','btn'))}<div class="board-toolbar"><div class="scene-label"><i class="scene-square"></i><b>SC 01</b><span>${esc(p.subtitle||'当前场景')}</span></div><div class="toolbar-right"><label class="search">${icon('search',15)}<input id="search" placeholder="搜索镜头" value="${esc(S.search)}"></label><div class="segmented"><button aria-label="卡片视图" class="${S.view==='grid'?'selected':''}" data-action="view" data-view="grid">${icon('grid',15)}</button><button aria-label="列表视图" class="${S.view==='list'?'selected':''}" data-action="view" data-view="list">${icon('list',17)}</button></div></div></div><div class="scroll-body"><div class="notice-line"><span>${icon('info',13)}内置素材为原创概念图与动态演示，非 AI 平台生成</span><button data-action="route" data-route="connections">自定义生成连接 ${icon('arrow',13)}</button></div>${shots.length?`<div class="shot-grid ${S.view==='list'?'list-view':''}">${shots.map(s=>`<article class="shot-card ${S.shotId===s.id?'selected':''}" draggable="true" data-drag-shot="${s.id}" data-action="select-shot" data-id="${s.id}"><div class="card-art">${art(media(s.keyframeId))}<span class="shot-code">${esc(s.code)}</span><span class="frame-duration">${s.duration.toFixed(1)}s</span><button class="art-preview" aria-label="预览镜头" data-action="preview" data-id="${s.videoId||s.keyframeId||''}">${icon(s.videoId?'play':'eye',20)}</button>${s.videoId?'<span class="video-badge">'+icon('video',12)+' 视频已就绪</span>':''}</div><div class="card-info"><div class="card-title"><h3>${esc(s.title)}</h3><span class="status ${s.videoId?'good':s.keyframeId?'warm':''}"><i></i>${s.videoId?'已采用':s.keyframeId?'关键帧':'待制作'}</span></div><p>${esc(s.description)}</p><div class="card-meta"><span>${esc(s.size)} <i>·</i> ${esc(s.camera)}</span><button aria-label="复制镜头" data-action="duplicate-shot" data-id="${s.id}">${icon('copy',13)}</button></div></div></article>`).join('')}</div>`:blank('给故事一个开始','从剧本拆镜，或者手动添加第一个镜头。','add-shot','添加镜头')}<div class="board-bottom"><span>${icon('link',13)}所有资产、提示词和生成版本都与镜头关联</span><span>拖动卡片调整顺序</span></div></div></section>${S.inspector?inspector():''}</div>`;}
function inspector(){const s=selected();if(!s)return`<aside class="inspector">${blank('尚无镜头','添加镜头后即可编辑。')}</aside>`;const refs=S.project.assets.filter(a=>(s.assetIds||[]).includes(a.id));return`<aside class="inspector"><div class="inspector-heading"><span>${icon('settings',15)}镜头详情</span><span class="mono">${esc(s.code)}</span></div><div class="inspector-scroll"><div class="inspector-art">${art(media(s.keyframeId))}<button data-action="import-shot">${icon('upload',13)}替换参考</button></div><div class="inspector-title"><span class="eyebrow">SHOT DETAILS</span>${field('镜头名称','title',s.title)}</div><div class="field-row">${field('景别','size',s.size,{options:['远景','全景','中景','中近景','近景','特写']})}${field('时长 / 秒','duration',s.duration,{type:'number',extra:'min="1" max="120" step="0.5"'})}</div>${field('画面描述','description',s.description,{area:true,extra:'rows="3"'})}${field('机位与角度','angle',s.angle)}${field('镜头运动','camera',s.camera,{options:['固定镜头','缓慢推进','轻推','缓慢拉远','跟随','横移','环绕']})}<div class="section-label">引用资产<span>${refs.length} 项</span></div><div class="asset-chips">${refs.map(a=>`<button class="asset-chip" data-action="asset-focus" data-id="${a.id}">${art(media(a.mediaId))}<span>${esc(a.name)}</span></button>`).join('')||'<small>尚未绑定资产</small>'}${button(icon('plus',13),'bind-assets','','chip-add')}</div><div class="section-label">生成提示词<span>中文</span></div><textarea data-bind="shot.prompt" class="prompt-area" rows="4">${esc(s.prompt)}</textarea><details class="dialogue-details"><summary>原文台词 <span>手动编辑</span></summary><textarea data-bind="shot.dialogue" rows="2">${esc(s.dialogue)}</textarea></details><div class="inspector-footnote">${icon('info',13)}生成后保留候选版本，由你决定采用哪一版。</div></div><div class="inspector-actions">${button(icon('spark',15)+'生成关键帧','generate-image','','btn primary full')}${button(icon('video',15)+'生成视频','generate-video','','btn full')}</div></aside>`;}
function scriptPage(){const p=S.project;return`<section class="main-content">${heading('SCRIPT / 故事的起点','剧本工作室','保留原文，先确定故事，再安排每个镜头。',button(icon('upload',16)+'导入文本','import-script')+button(icon('spark',16)+'生成拆镜草稿','split-script','','btn primary'))}<div class="script-layout"><div class="script-document"><div class="document-top"><span>${icon('script',15)}剧本原文</span><small>手动编辑 · 自动保存</small></div><input class="script-title" data-bind="project.title" value="${esc(p.title)}" placeholder="给作品起个名字"><div class="script-spec">原创短片 <span>·</span> ${p.ratio} <span>·</span> ${p.fps} FPS</div><textarea class="script-editor" data-bind="project.script" placeholder="在这里写下你的故事…">${esc(p.script)}</textarea><div class="document-bottom"><span>${p.script.length} 字</span><span>支持 TXT / Markdown</span></div></div><div class="script-guide"><div class="section-label">制作脉络 <span>WORKFLOW</span></div>${[['script','写下故事','剧本保留在项目中，可随时修改。'],['assets','确定资产','为角色、场景与道具建立视觉参考。'],['grid','拆分镜头','按段落生成草稿，逐镜调整时长与机位。'],['video','生成与剪辑','选定素材，再进入粗剪时间线。']].map(([ic,t,d],i)=>`<div class="guide-step"><div>${icon(ic,17)}</div><span><b>${t}</b><p>${d}</p></span><small>0${i+1}</small></div>`).join('')}<div class="plain-note">${icon('info',16)}<p>Demo 使用本地分段规则拆镜，不会调用语言模型，也不会自动改写台词。</p></div><div class="project-settings">${field('画幅','ratio',p.ratio,{options:['16:9','9:16'],scope:'project'})}<p>画幅修改会应用到后续粗剪导出。</p></div></div></div></section>`;}
const assetLabels={character:'角色',scene:'场景',prop:'道具',style:'风格'};
function assetPage(){const a=S.project.assets.filter(a=>S.assetType==='all'||a.type===S.assetType);return`<section class="main-content">${heading('ASSETS / 视觉档案','资产库','从一个角色、一处场景，建立整个故事的视觉语言。',button(icon('plus',16)+'新建资产','new-asset','','btn primary'))}<div class="filter-tabs">${[['all','全部资产'],...Object.entries(assetLabels)].map(([id,n])=>`<button class="${S.assetType===id?'active':''}" data-action="asset-filter" data-filter="${id}">${n}<span>${id==='all'?S.project.assets.length:S.project.assets.filter(a=>a.type===id).length}</span></button>`).join('')}</div><div class="scroll-body"><div class="asset-grid">${a.map(a=>`<article class="asset-card"><div class="asset-art">${art(media(a.mediaId))}<span>${assetLabels[a.type]||'资产'}</span><button aria-label="预览资产" data-action="preview" data-id="${a.mediaId||''}">${icon('eye',17)}</button></div><div class="asset-card-body"><h3>${esc(a.name)}<small>参考档案</small></h3><p>${esc(a.description)}</p><div class="asset-controls">${button(icon('upload',14)+'导入参考','import-asset',`data-id="${a.id}"`,'btn small')}${button(icon('spark',14)+'生成','generate-asset',`data-id="${a.id}"`,'btn small warm')}${button(icon('settings',14),'edit-asset',`data-id="${a.id}" aria-label="编辑资产"`,'icon-btn')}</div></div></article>`).join('')}<button class="new-asset-card" data-action="new-asset">${icon('plus',26)}<b>添加新资产</b><span>角色 · 场景 · 道具 · 风格</span></button></div></div></section>`;}
function mediaPage(){const list=S.project.media.filter(m=>S.mediaKind==='all'||m.kind===S.mediaKind);return`<section class="main-content">${heading('MEDIA / 所有创作版本','视频素材','导入或生成，在这里比较、预览与采用。',button(icon('upload',16)+'导入素材','import-media')+button(icon('clock',16)+'任务中心','tasks','','btn primary'))}<div class="filter-tabs">${[['all','全部素材'],['video','视频'],['image','图片']].map(([id,n])=>`<button class="${S.mediaKind===id?'active':''}" data-action="media-filter" data-filter="${id}">${n}<span>${id==='all'?S.project.media.length:S.project.media.filter(m=>m.kind===id).length}</span></button>`).join('')}</div><div class="scroll-body"><div class="media-grid">${list.map(m=>{const s=shot(m.shotId),adopted=S.project.shots.some(s=>s.videoId===m.id||s.keyframeId===m.id)||S.project.assets.some(a=>a.mediaId===m.id);return`<article class="media-card"><button class="media-art" data-action="preview" data-id="${m.id}">${m.kind==='video'?`<video src="${esc(url(m))}" preload="metadata" muted></video><span class="play-circle">${icon('play',22)}</span>`:art(m)}<span class="media-format">${m.kind==='video'?'VIDEO':'IMAGE'}</span>${m.demo?'<span class="demo-tag">演示</span>':''}</button><div class="media-card-body"><h3>${esc(m.name)}</h3><p>${esc(s?.code||'资产 / 外部素材')}${m.duration?' · '+m.duration.toFixed(1)+'s':''}</p><div>${button(icon(adopted?'check':'plus',14)+(adopted?'已采用':'采用素材'),'adopt',`data-id="${m.id}"`,adopted?'btn small adopted':'btn small primary')}${!m.shotId&&!m.assetId?'<span class="muted">选择镜头后采用</span>':''}</div></div></article>`;}).join('')||blank('素材库还是空的','生成关键帧或导入已有素材，即可继续制作。','import-media','导入素材')}</div></div></section>`;}
function editorPage(){const p=S.project,clips=cutList(p),clip=clips.find(c=>c.id===S.clipId)||clips[0];if(clip)S.clipId=clip.id;const m=media(clip?.mediaId),s=shot(clip?.shotId);const total=durationOf(p.timeline);return`<section class="main-content edit-page">${heading('ROUGH CUT / 让镜头成为故事','粗剪台',`${p.timeline.length} 个片段 <i>·</i> ${timecode(total,p.fps)} <i>·</i> ${p.ratio} / ${p.fps} FPS`,button(icon('grid',15)+'一键铺排','autofill')+button(icon('download',15)+(S.rendering?`导出中 ${S.renderProgress}%`:'导出 MP4'),'render-movie',S.rendering?'disabled':'','btn primary'))}<div class="editor-stage"><div class="preview-monitor"><div class="monitor-top"><span><i class="dot"></i>节目预览</span><span>${esc(s?.code||'SEQUENCE 01')} <i>·</i> ${esc(s?.title||p.title)}</span><span>${p.width} × ${p.height}</span></div><div class="monitor-image">${m?(m.kind==='video'?`<video id="timeline-player" src="${esc(url(m))}" playsinline preload="metadata" ${clip.muted?'muted':''}></video>`:art(m)):blank('先把镜头放进时间线','一键铺排已采用的视频素材，或回到分镜完成生成。','autofill','铺排已采用素材')}</div><div class="monitor-controls"><span id="edit-timecode" class="mono">${timecode(clip?.start||0,p.fps)}</span><div>${button(icon('back',16),'prev-clip','','icon-btn')}${button(icon(S.playing?'pause':'play',20),'toggle-play','','transport-play')}${button(icon('arrow',16),'next-clip','','icon-btn')}</div><span class="mono muted">${timecode(total,p.fps)}</span></div></div><aside class="cut-inspector"><div class="section-label">片段属性<span>${esc(s?.code||'—')}</span></div><h3>${esc(s?.title||'选择片段')}</h3>${clip?`<p>${esc(m?.name||'')}</p><div class="field-row"><label class="field"><span>源入点 / 秒</span><input type="number" step="0.1" min="0" data-trim="in" value="${clip.in}"></label><label class="field"><span>源出点 / 秒</span><input type="number" step="0.1" min="0.1" data-trim="out" value="${clip.out}"></label></div><div class="cut-duration"><span>选段时长</span><strong>${(clip.out-clip.in).toFixed(2)}<small>s</small></strong></div><label class="checkbox"><input type="checkbox" data-clip-muted ${clip.muted?'checked':''}>静音原素材</label><div class="cut-buttons">${button(icon('back',15)+'前移','move-clip',`data-dir="-1"`,'btn small')}${button('后移'+icon('arrow',15),'move-clip',`data-dir="1"`,'btn small')}${button(icon('trash',15),'delete-clip','aria-label="删除片段"','icon-btn danger')}</div><div class="plain-note">${icon('info',15)}<p>剪辑不改变原始素材。先调整节奏，再导出粗剪。</p></div>`:'<p>选中下方时间线片段进行编辑。</p>'}</aside></div><div class="timeline-panel"><div class="timeline-toolbar"><span>${icon('cut',17)}<b>SEQUENCE 01</b><small>主序列</small></span><div>${button(icon('undo',15),'undo','','icon-btn')}${button(icon('undo',15),'redo','','icon-btn redo')}${button(icon('grid',15)+'重建铺排','autofill','','btn small')}</div></div><div class="timeline-scroll"><div class="time-ruler"><div class="track-label">${p.fps} FPS</div><div>${Array.from({length:Math.max(6,Math.ceil(total/5)+1)},(_,i)=>`<span>${timecode(i*5,p.fps).slice(0,5)}</span>`).join('')}</div></div><div class="track-row"><div class="track-label"><b>V1</b>${icon('video',14)}</div><div class="timeline-clips">${clips.map((c,i)=>{const m=media(c.mediaId);const thumb=m?.kind==='image'?m:media(shot(c.shotId)?.keyframeId);return`<button class="timeline-clip ${clip?.id===c.id?'active':''}" style="width:${Math.max(95,c.duration*30)}px" draggable="true" data-drag-clip="${c.id}" data-action="select-clip" data-id="${c.id}"><span class="clip-top">${esc(shot(c.shotId)?.code||'片段')}<small>${c.duration.toFixed(1)}s</small></span><div>${thumb?art(thumb):'<i></i>'}${thumb?art(thumb):'<i></i>'}</div></button>`;}).join('')||'<span class="timeline-empty">已采用的视频会出现在这里</span>'}</div></div><div class="track-row audio"><div class="track-label"><b>A1</b>${icon('sound',14)}</div><div><span>素材原声随视频剪辑 · 默认不添加配乐</span></div></div></div><div class="timeline-footer"><span>${icon('info',13)}拖动片段可调整顺序 · 入出点以秒编辑，导出按项目帧率对齐</span><span>${p.timeline.length} CLIPS</span></div></div></section>`;}
function connectionPage(){const c=S.editConn;return`<section class="main-content">${heading('CONNECTIONS / YOUR TOOLS, YOUR CHOICE','连接与模型','按你的方式接入平台。CLI 和 API，都由你定义。',button('连接 Pixmax CLI','add-pixmax','','btn')+button(icon('plus',16)+'添加连接','add-connection','','btn primary'))}<div class="connections-layout"><div class="connection-sidebar"><div class="demo-connection"><span class="connection-logo">${icon('spark',23)}</span><div><h3>内置演示连接</h3><p>无需密钥 · 全流程体验</p></div><i class="dot"></i></div>${S.connections.map(c=>`<button class="connection-item ${S.editConn?.id===c.id?'active':''}" data-action="select-connection" data-id="${c.id}"><span class="connector-type">${c.type.toUpperCase()}</span><span><b>${esc(c.name)}</b><small>${c.outputKind==='image'?'图像生成':'视频生成'} · ${esc(c.model||'自定义模型')}</small></span>${icon('chevron',13)}</button>`).join('')}<div class="connection-help">${icon('info',16)}<p>真实请求只会在你点击生成并确认费用后发出。配置检查不产生生成任务。</p></div><div class="ffmpeg-settings"><div class="section-label">粗剪渲染工具</div><label class="field"><span>FFmpeg 可执行文件</span><input id="ffmpeg-path" value="${esc(S.ffmpegPath)}" placeholder="ffmpeg 或完整程序路径"></label><div>${button('选择文件','choose-ffmpeg','','btn small')}${button('保存路径','save-ffmpeg','','btn small')}</div><p>MP4导出需本机安装FFmpeg；Windows便携包不内置此工具。</p></div></div><div class="connection-editor">${c?connectionForm(c):`<div class="connection-welcome"><div class="large-plug">${icon('plug',36)}</div><h2>把你的工具，接进创作流程</h2><p>连接任意返回图片或视频的程序与接口。<br>无需更改项目、镜头或时间线。</p><div class="connection-options">${button('<b>Pixmax CLI</b><span>导入技能 ZIP 或选择 CLI<br>自动读取登录、画布与模型</span>','add-pixmax','','connection-option')}${button('<b>CLI</b><span>可执行程序 + 参数数组<br>通过标准输入传入请求 JSON</span>','add-cli','','connection-option')}${button('<b>HTTP API</b><span>自定义请求模板<br>支持同步结果与异步轮询</span>','add-api','','connection-option')}</div><small>${S.desktop?'密钥只保存在本机，项目交接不包含连接配置。':'当前是浏览器预览：真实调用与密钥保存请使用桌面客户端。'}</small></div>`}</div></div></section>`;}
function pixmaxForm(c){const st=c.pixmaxStatus;return `<div class="connection-form-heading"><h2>连接 Pixmax CLI</h2><div>${button('检查连接','check-connection','','btn primary')}${button('保存','save-connection','','btn')}${button('移除','delete-connection','','btn')}</div></div><div class="connection-form-scroll"><p class="form-help">导入 Pixmax 技能 ZIP，或选择已安装的 CLI。客户端自动读取已有登录与默认画布，无需填写请求参数和结果字段。</p>${button('导入 CLI ZIP 包','import-pixmax','','btn')}${field(c.runtimeRoot?'Python 3.10+ 程序路径':'Pixmax 可执行程序路径','program',c.program,{scope:'connection'})}${button('选择程序','choose-cli','','btn small')}${field('连接名称','name',c.name,{scope:'connection'})}${field('输出类型','outputKind',c.outputKind,{options:['image','video'],scope:'connection'})}${field('画布 UUID · 留空使用 CLI 默认画布','fileUuid',c.fileUuid||'',{scope:'connection'})}${st?.models?.length?`<label class="field"><span>模型</span><select data-bind="connection.model"><option value="">自动选择可用模型</option>${st.models.map(m=>`<option value="${esc(m.code)}" ${m.code===c.model?'selected':''}>${esc(m.name)} · ${esc(m.code)}</option>`).join('')}</select></label>`:field('模型 ID · 留空自动读取','model',c.model,{scope:'connection'})}${field('平台密钥 · 可留空复用 CLI 登录','token',c.token||'',{type:'password',scope:'connection',extra:'autocomplete="off"'})}<p class="form-help">未登录时，请先在本机终端运行 pixmax auth login web，在浏览器完成授权后重新检查。导入包需要本机 Python 3.10+；不自动安装程序或复制账号密钥。</p>${st?`<div role="status"><h3>${st.authVerified?'账号已验证':'连接检查结果'}</h3><p>${esc(st.message)}</p><p>环境：${esc(st.environment||'未读取')} · 画布：${esc(st.fileUuid||'未选择')}</p></div>`:''}<p class="form-help">检查只运行自检、只读查询与 dry-run，不创建节点、不提交生成。当前附带 CLI 的生成协议存在兼容性缺口，生成入口会明确阻止提交。</p></div>`;}
function connectionForm(c){if(c.provider==='pixmax')return pixmaxForm(c);return`<div class="connection-form-heading"><div><span class="eyebrow">${c.type==='cli'?'COMMAND LINE':'HTTP ENDPOINT'}</span><h2>${esc(c.name||'新的连接')}</h2></div><div>${button(icon('trash',16),'delete-connection','','icon-btn danger')}${button('检查配置','check-connection','','btn')}${button(icon('check',15)+'保存连接','save-connection','','btn primary')}</div></div><div class="connection-form-scroll"><div class="field-row">${field('连接名称','name',c.name,{scope:'connection'})}${field('输出类型','outputKind',c.outputKind,{options:['image','video'],scope:'connection'})}</div>${field('模型名称或ID','model',c.model,{scope:'connection'})}${c.type==='api'?`${field('提交地址 · POST','url',c.url,{scope:'connection',extra:'placeholder="https://your-platform.example/v1/generate"'})}${field('请求头 JSON · 不含密钥','headers',c.headers,{area:true,extra:'rows="2"',scope:'connection'})}${field('请求体 JSON 模板','bodyTemplate',c.bodyTemplate,{area:true,extra:'rows="6" class="code-input"',scope:'connection'})}<div class="variable-help"><b>可用变量</b><code>{{prompt}}</code><code>{{model}}</code><code>{{duration}}</code><code>{{ratio}}</code><code>{{firstFrame}}</code><code>{{references}}</code></div>`:`${field('可执行程序路径','program',c.program,{scope:'connection',extra:'placeholder="C:\\Python312\\python.exe"'})}${button(icon('folder',14)+'选择程序','choose-cli','','btn small')}${field('参数数组 JSON','args',c.args,{area:true,extra:'rows="3" class="code-input"',scope:'connection'})}<div class="variable-help"><b>可用变量</b><code>{{inputFile}}</code><code>{{outputDir}}</code><code>{{prompt}}</code><code>{{referencePath}}</code></div><p class="form-help">请求JSON同时通过stdin发送。推荐参数只传脚本路径和 {{inputFile}}，不需要把提示词拼接成命令。</p>${field('密钥环境变量名','tokenEnv',c.tokenEnv,{scope:'connection'})}${field('CLI 等待上限 / 秒','timeoutSeconds',c.timeoutSeconds||180,{type:'number',scope:'connection',extra:'min="10" max="900"'})}`}
<div class="connection-section-title">密钥与结果映射</div>${field(c.hasSecret?'平台密钥 · 已保存，留空保留':'平台密钥 · 可留空','token',c.token||'',{type:'password',scope:'connection',extra:'autocomplete="off"'})}${c.type==='api'?`<div class="field-row">${field('密钥请求头','tokenHeader',c.tokenHeader,{scope:'connection'})}${field('密钥前缀','tokenPrefix',c.tokenPrefix,{scope:'connection'})}</div>`:''}<p class="form-help">${S.desktop?(S.secretPersistent?'密钥使用本机系统加密保存，不进入项目交接包。':'系统安全存储当前不可用，密钥仅在本次会话保留。'):'浏览器预览不保存密钥，也不执行真实API或CLI。'}</p><div class="field-row">${field('输出字段路径','outputPath',c.outputPath,{scope:'connection',extra:'placeholder="data.0.url"'})}${field('结果表示','outputFormat',c.outputFormat,{options:c.type==='cli'?['url','path','base64']:['url','base64'],scope:'connection'})}</div>${c.type==='api'?`<label class="checkbox"><input type="checkbox" data-bind="connection.downloadWithAuth" ${c.downloadWithAuth?'checked':''}>同源媒体下载也需要鉴权</label><label class="checkbox"><input type="checkbox" data-bind="connection.async" ${c.async?'checked':''}>这是异步任务 API</label>${c.async?`${field('查询地址 · 使用 {{taskId}}','pollUrl',c.pollUrl,{scope:'connection'})}${field('查询方法','pollMethod',c.pollMethod||'GET',{options:['GET','POST'],scope:'connection'})}${c.pollMethod==='POST'?field('查询请求体 JSON · 可用 {{taskId}}','pollBodyTemplate',c.pollBodyTemplate||'{}',{area:true,extra:'rows="3"',scope:'connection'}):''}<div class="field-row">${field('提交响应的任务ID字段','taskIdPath',c.taskIdPath,{scope:'connection'})}${field('查询响应的状态字段','statusPath',c.statusPath,{scope:'connection'})}</div><div class="field-row">${field('成功状态 · 逗号分隔','successValues',c.successValues,{scope:'connection'})}${field('失败状态 · 逗号分隔','failureValues',c.failureValues,{scope:'connection'})}</div>${field('轮询间隔 / 秒','pollInterval',c.pollInterval,{type:'number',scope:'connection',extra:'min="1" max="60"'})}<p class="form-help">结果字段路径应用于查询成功的JSON响应，恢复查询不会重新提交生成。</p>`:''}`:''}<details class="protocol-details"><summary>查看输入输出示例</summary><pre>${esc(c.type==='cli'?'stdin / request.json\n{"prompt":"雨夜旧车站","duration":5,"references":[],"output_directory":"..."}\n\nstdout 最后一条 JSON\n{"output":{"path":"C:/work/result.png"}}\n\n结果字段：output.path，表示：path':'同步响应\n{"data":[{"url":"https://.../result.png"}]}\n\n异步提交响应\n{"id":"task-123"}\n\n查询响应\n{"status":"succeeded","data":[{"url":"https://.../result.mp4"}]}')}</pre></details></div>`;}
function render(){const app=$('#app');app.innerHTML=`<div class="shell">${sidebar()}<main class="main-shell">${topbar()}${({board,script:scriptPage,assets:assetPage,media:mediaPage,edit:editorPage,connections:connectionPage}[S.route])()}<footer class="statusbar"><span><i class="dot"></i>${S.desktop?'桌面客户端':'浏览器预览'}<i>·</i>本地项目</span><span>FilmDock <b>0.2 DEMO</b></span><span>${S.project.ratio}<i>·</i>${S.project.fps} FPS<i>·</i>${S.project.shots.length} SHOTS</span></footer></main></div>`;if(S.route==='edit')attachPlayer();}
function modal(html,wide=false){S.modal=true;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><button aria-label="关闭" class="modal-close" data-action="close-modal">${icon('x',18)}</button>${html}</section></div>`;}
function closeModal(){S.modal=false;$('#modal-root').innerHTML='';}
function newConnection(type='api'){S.editConn={id:uid(),name:type==='api'?'自定义 API':'自定义 CLI',type,outputKind:'image',model:'',url:'',headers:'{}',bodyTemplate:'{\n  "model": "{{model}}",\n  "prompt": "{{prompt}}"\n}',token:'',tokenHeader:'Authorization',tokenPrefix:'Bearer ',outputPath:type==='api'?'data.0.url':'output.path',outputFormat:type==='api'?'url':'path',program:'',args:'[]',tokenEnv:'API_KEY',timeoutSeconds:180,downloadWithAuth:false,pollMethod:'GET',pollBodyTemplate:'{"task_id":"{{taskId}}"}',async:false,taskIdPath:'id',pollUrl:'',statusPath:'status',successValues:'succeeded,completed,success',failureValues:'failed,error,cancelled',pollInterval:5};S.route='connections';render();}
function generateModal(kind,assetId=null){const s=selected(),a=S.project.assets.find(a=>a.id===assetId),target=a||s;if(!target){toast('请先添加镜头或资产',true);return;}const c=S.connections.filter(c=>c.outputKind===kind);modal(`<div class="modal-eyebrow">${kind==='image'?'IMAGE GENERATION':'VIDEO GENERATION'}</div><h2>${kind==='image'?'生成关键帧':'生成视频素材'}</h2><p class="modal-description">${esc(target.title||target.name)} · 结果将作为新候选保存</p><form id="generation-form" data-kind="${kind}" data-shot="${a?'':s.id}" data-asset="${assetId||''}"><label class="field"><span>选择连接</span><select name="connection"><option value="demo">内置演示 · 免费 · 非AI生成</option>${c.map(c=>`<option value="${c.id}" ${S.desktop?'':'disabled'}>${esc(c.name)} · ${c.type.toUpperCase()}</option>`).join('')}</select></label><label class="field"><span>提示词</span><textarea name="prompt" rows="5">${esc(target.prompt||target.description)}</textarea></label>${kind==='video'?`<div class="field-row"><label class="field"><span>生成时长 / 秒</span><input name="duration" type="number" min="1" max="30" value="${s?.duration||5}"></label><label class="field"><span>首帧参考</span><input readonly value="${s?.keyframeId?'当前采用的关键帧':'尚未采用首帧'}"></label></div>`:''}<label class="checkbox"><input type="checkbox" name="acknowledged">使用真实连接时，我确认本次调用可能产生平台费用</label><p class="form-help">演示连接只返回内置概念素材，不会向任何平台发送请求。真实结果需要匹配你配置的输出字段。</p><div class="modal-actions">${button('配置新连接','open-connections','','btn')}<button class="btn primary" type="submit">${icon('spark',16)}开始生成</button></div></form>`);}
function remember(){S.undo.push(clone(S.project.timeline));if(S.undo.length>30)S.undo.shift();S.redo=[];}
function attachPlayer(){const v=$('#timeline-player');if(!v)return;const c=S.project.timeline.find(c=>c.id===S.clipId);if(!c)return;v.addEventListener('loadedmetadata',()=>{v.currentTime=c.in;if(S.playing)v.play().catch(()=>{S.playing=false;});},{once:true});let switching=false;v.addEventListener('timeupdate',()=>{const cuts=cutList(S.project),clip=cuts.find(x=>x.id===S.clipId);if(!clip)return;const el=$('#edit-timecode');if(el)el.textContent=timecode(clip.start+Math.max(0,v.currentTime-clip.in),S.project.fps);if(S.playing&&!switching&&v.currentTime>=clip.out-.03){switching=true;nextClip(true);}});v.addEventListener('ended',()=>{if(S.playing&&!switching){switching=true;nextClip(true);}});v.addEventListener('error',()=>toast('素材无法播放，请检查导入文件或重新生成',true));}
function nextClip(advance=false,dir=1){const i=S.project.timeline.findIndex(c=>c.id===S.clipId),n=i+dir;if(n>=0&&n<S.project.timeline.length){S.clipId=S.project.timeline[n].id;if(!advance)S.playing=false;}else S.playing=false;render();}
async function replaceBootstrap(data){if(!data)return;Object.assign(S,{project:data.project,connections:data.connections,desktop:data.desktop,secretPersistent:data.secretPersistent,ffmpegPath:data.ffmpegPath||S.ffmpegPath});S.shotId=S.project.shots[0]?.id;S.clipId=null;S.undo=[];S.redo=[];S.playing=false;closeModal();render();}
async function saveConnection(){if(!S.editConn)return;const list=S.connections.filter(c=>c.id!==S.editConn.id).concat(clone(S.editConn));const r=await api.saveConnections({connections:list,ffmpegPath:S.ffmpegPath});S.connections=r.connections;S.secretPersistent=r.secretPersistent;S.editConn=clone(S.connections.find(c=>c.id===S.editConn.id));S.editConn.token='';render();toast('连接配置已保存，真实调用将在确认后发出');}
async function adopt(id){const m=media(id);if(!m)return;let target=m.assetId?S.project.assets.find(a=>a.id===m.assetId):shot(m.shotId)||selected();if(!target){toast('请先在分镜画板选择一个镜头',true);return;}if(m.assetId)target.mediaId=id;else if(m.kind==='image')target.keyframeId=id;else if(m.kind==='video'){target.videoId=id;target.status='adopted';}else return;changed();render();toast('已采用当前版本，原候选仍保留');}
async function handleAction(e){const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='route'){S.route=el.dataset.route;S.playing=false;closeModal();render();}
 else if(a==='select-shot'){S.shotId=id;render();}
 else if(a==='view'){S.view=el.dataset.view;render();}
 else if(a==='window')await api.window(el.dataset.window);
 else if(a==='close-modal')closeModal();
 else if(a==='preview'){const m=media(id);if(!m){toast('还没有可预览素材',true);return;}modal(`<div class="modal-eyebrow">${m.demo?'内置演示素材 · 非AI生成':'PROJECT MEDIA'}</div><h2>${esc(m.name)}</h2><div class="preview-modal">${m.kind==='video'?`<video src="${esc(url(m))}" controls autoplay playsinline></video>`:art(m)}</div><div class="modal-actions"><span class="muted">候选版本保存在本地项目中</span>${button(icon('check',15)+'采用素材','adopt',`data-id="${id}"`,'btn primary')}</div>`,true);}
 else if(a==='adopt'){await adopt(id);closeModal();}
 else if(a==='add-shot'){const n=S.project.shots.length+1,s={id:uid(),code:`SH ${String(n).padStart(3,'0')}`,title:'新的镜头',description:'在这里描述画面、人物动作和镜头关系。',duration:5,size:'中景',angle:'人物侧前方机位',camera:'固定镜头',dialogue:'',prompt:'',assetIds:[],keyframeId:null,videoId:null,status:'draft'};S.project.shots.push(s);S.shotId=s.id;S.route='board';changed();render();}
 else if(a==='duplicate-shot'){const original=shot(id);const copy={...clone(original),id:uid(),title:original.title+' · 副本',videoId:null,status:'draft'};S.project.shots.splice(S.project.shots.findIndex(s=>s.id===id)+1,0,copy);S.project.shots.forEach((s,i)=>s.code=`SH ${String(i+1).padStart(3,'0')}`);S.shotId=copy.id;changed();render();toast('镜头已复制，可单独调整');}
 else if(a==='generate-image')generateModal('image');
 else if(a==='generate-video')generateModal('video');
 else if(a==='generate-asset')generateModal('image',id);
 else if(a==='open-connections'){closeModal();S.route='connections';render();}
 else if(a==='import-script'){const text=await api.importScript();if(text!==null){S.project.script=text;changed();render();toast('剧本原文已导入');}}
 else if(a==='split-script'){if(!S.project.script.trim()){toast('请先写下或导入剧本',true);return;}modal(`<div class="modal-eyebrow">LOCAL BREAKDOWN</div><h2>生成拆镜草稿</h2><p class="modal-description">按段落拆成镜头草稿，保留原文台词。当前 ${S.project.shots.length} 个镜头将保留，可以把草稿追加到后面。</p><div class="plain-note">${icon('info',17)}<p>这是本地分段规则，景别、机位与时长需要你逐镜确认。</p></div><div class="modal-actions">${button('取消','close-modal')}${button('追加拆镜草稿','confirm-split','','btn primary')}</div>`);}
 else if(a==='confirm-split'){const shots=splitScript(S.project.script),n=S.project.shots.length;shots.forEach((s,i)=>s.code=`SH ${String(n+i+1).padStart(3,'0')}`);S.project.shots.push(...shots);S.shotId=shots[0]?.id;S.route='board';changed();closeModal();render();toast(`已追加 ${shots.length} 个镜头草稿`);}
 else if(a==='asset-filter'){S.assetType=el.dataset.filter;render();}
 else if(a==='media-filter'){S.mediaKind=el.dataset.filter;render();}
 else if(a==='new-asset'||a==='edit-asset'){const a=S.project.assets.find(x=>x.id===id)||{id:uid(),name:'',type:'character',description:'',mediaId:null};modal(`<div class="modal-eyebrow">VISUAL ASSET</div><h2>${id?'编辑资产':'新建资产'}</h2><form id="asset-form" data-id="${a.id}"><label class="field"><span>资产名称</span><input name="name" required value="${esc(a.name)}" placeholder="角色、场景或道具名称"></label><label class="field"><span>资产类型</span><select name="type">${Object.entries(assetLabels).map(([k,v])=>`<option value="${k}" ${a.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>视觉描述</span><textarea name="description" rows="4" required>${esc(a.description)}</textarea></label><div class="modal-actions">${button('取消','close-modal')}<button class="btn primary" type="submit">保存资产</button></div></form>`);}
 else if(a==='asset-focus'){S.route='assets';S.assetType='all';render();}
 else if(a==='bind-assets'){const s=selected();modal(`<h2>为镜头引用资产</h2><p class="modal-description">${esc(s.title)}</p><form id="bind-form">${S.project.assets.map(a=>`<label class="check-asset"><input type="checkbox" name="asset" value="${a.id}" ${s.assetIds?.includes(a.id)?'checked':''}>${art(media(a.mediaId))}<span><b>${esc(a.name)}</b><small>${assetLabels[a.type]}</small></span></label>`).join('')}<div class="modal-actions">${button('取消','close-modal')}<button type="submit" class="btn primary">保存引用</button></div></form>`);}
 else if(['import-shot','import-asset','import-media'].includes(a)){await flush();const target=a==='import-asset'?{assetId:id}:a==='import-shot'?{shotId:selected()?.id}:{};const list=await api.importMedia(target);for(const m of list){if(!S.project.media.some(x=>x.id===m.id))S.project.media.push(m);}if(list.length){if(a==='import-asset')S.project.assets.find(a=>a.id===id).mediaId=list[0].id;else if(a==='import-shot')selected().keyframeId=list.find(m=>m.kind==='image')?.id||selected().keyframeId;changed();render();toast(`已导入 ${list.length} 份素材`);}}
 else if(a==='project-menu'){modal(`<div class="modal-eyebrow">LOCAL PROJECT</div><h2>${esc(S.project.title)}</h2><div class="project-menu">${button(icon('plus',18)+'新建空白项目','new-project')}${button(icon('folder',18)+'打开交接 ZIP','open-project')}${button(icon('film',18)+'恢复内置演示项目','confirm-reset')}</div><p class="form-help">切换前请导出当前项目，保留可继续制作的交接包。</p>`);}
 else if(a==='new-project'){modal(`<h2>新建项目</h2><form id="new-project-form"><label class="field"><span>项目名称</span><input required name="title" placeholder="你的下一个故事"></label><p class="form-help">当前项目请先导出保存。新项目从空白剧本开始。</p><div class="modal-actions">${button('取消','close-modal')}<button type="submit" class="btn primary">创建项目</button></div></form>`);}
 else if(a==='open-project'){await flush();const data=await api.openProject();if(data){await replaceBootstrap(data);toast('项目已打开');}}
 else if(a==='confirm-reset')modal(`<h2>恢复演示项目</h2><p class="modal-description">将当前工作区切换为《雨停之前》。请先导出当前项目，避免丢失未交接的工作。</p><div class="modal-actions">${button('取消','close-modal')}${button('导出当前项目','export-package')}${button('恢复演示','reset-demo','','btn primary')}</div>`);
 else if(a==='reset-demo')await replaceBootstrap(await api.resetDemo());
 else if(a==='handoff'){const p=S.project;modal(`<div class="modal-eyebrow">PROJECT HANDOFF</div><h2>把创作完整交给下一程</h2><p class="modal-description">${esc(p.title)} · 可在另一个目录继续打开制作</p><div class="handoff-stats">${[[p.shots.length,'镜头'],[p.assets.length,'资产'],[p.media.length,'素材'],[p.timeline.length,'剪辑片段']].map(([n,l])=>`<div><b>${n}</b><span>${l}</span></div>`).join('')}</div><div class="handoff-list">${['剧本原文与资产描述','镜头、提示词与采用记录','全部已归档图片和视频','可继续编辑的粗剪时间线','SHA256文件校验清单'].map(t=>`<p>${icon('check',16)}${t}</p>`).join('')}</div><p class="form-help">不包含密钥或连接配置。${p.media.some(m=>m.demo)?'项目含标注为演示的内置素材。':''}MP4成片请在粗剪台单独导出。</p><div class="modal-actions">${button('返回','close-modal')}${button(icon('download',16)+'导出项目 ZIP','export-package','','btn primary')}</div>`);}
 else if(a==='export-package'){await flush();el.disabled=true;el.textContent='正在打包…';const r=await api.exportPackage();if(r){closeModal();toast('项目交接包已导出');}else{closeModal();}}
 else if(a==='tasks'){const tasks=S.project.tasks;modal(`<div class="modal-eyebrow">TASK CENTER</div><h2>任务中心</h2><p class="modal-description">生成结果先入库，由你选择采用。</p><div class="task-list">${tasks.map(t=>`<article class="task-item"><span class="task-type">${icon(t.kind==='video'?'video':'spark',19)}</span><div><b>${esc(t.name)}</b><small>${t.demo?'内置演示':esc(S.connections.find(c=>c.id===t.connectionId)?.name||'自定义连接')} · ${statusLabel[t.status]||esc(t.status)}</small>${t.error?`<p>${esc(t.error)}</p>`:''}</div><span class="status ${t.status==='succeeded'?'good':'warm'}">${statusLabel[t.status]||esc(t.status)}</span>${t.mediaId?button('查看','preview',`data-id="${t.mediaId}"`,'btn small'):['running','submitting','downloading'].includes(t.status)?button('暂停等待','pause-task',`data-id="${t.id}"`,'btn small'):t.remoteId||t.downloadSource?button('恢复','resume-task',`data-id="${t.id}"`,'btn small'):''}</article>`).join('')||blank('暂时没有任务','从镜头详情生成第一张关键帧，或选择自定义连接。')}</div>`,true);}
 else if(a==='pause-task'){await api.pauseTask(id);closeModal();toast('已停止本地等待，请核对远端状态');}
 else if(a==='resume-task'){await api.resumeTask(id);closeModal();toast('正在恢复已有任务，不会重新提交生成');}
 else if(a==='add-connection'||a==='add-api')newConnection('api');
 else if(a==='add-pixmax'){newConnection('cli');Object.assign(S.editConn,{provider:'pixmax',name:'Pixmax CLI',program:'pixmax',args:'[]',tokenEnv:'PIXMAX_BEARER_TOKEN',timeoutSeconds:900});render();}
 else if(a==='import-pixmax'){if(!S.desktop)throw new Error('请在桌面客户端导入 CLI 包');const r=await api.importPixmax();if(r){Object.assign(S.editConn,r,{program:'python'});render();toast('CLI 已导入；请选择本机 Python 3.10+，再检查连接');}}
 else if(a==='add-cli')newConnection('cli');
 else if(a==='select-connection'){S.editConn=clone(S.connections.find(c=>c.id===id));S.editConn.token='';render();}
 else if(a==='save-connection')await saveConnection();
 else if(a==='check-connection'){await saveConnection();const r=await api.checkConnection(S.editConn.id);if(r.connections){S.connections=r.connections;S.editConn=clone(S.connections.find(c=>c.id===S.editConn.id));render();}toast(r.message);}
 else if(a==='delete-connection'){const id=S.editConn.id;modal(`<h2>移除连接配置</h2><p class="modal-description">不影响已生成的素材。远端运行任务需要在平台核对。</p><div class="modal-actions">${button('取消','close-modal')}${button('移除连接','confirm-delete-connection',`data-id="${id}"`,'btn primary')}</div>`);}
 else if(a==='confirm-delete-connection'){const r=await api.saveConnections({connections:S.connections.filter(c=>c.id!==id),ffmpegPath:S.ffmpegPath});S.connections=r.connections;S.editConn=null;closeModal();render();toast('连接已移除');}
 else if(a==='choose-cli'){const f=await api.chooseProgram();if(f){S.editConn.program=f;render();}else if(!S.desktop)toast('请在桌面客户端选择本机程序');}
 else if(a==='choose-ffmpeg'){const f=await api.chooseProgram();if(f){S.ffmpegPath=f;render();}}
 else if(a==='save-ffmpeg'){S.ffmpegPath=$('#ffmpeg-path').value;await api.saveConnections({connections:S.connections,ffmpegPath:S.ffmpegPath});toast('FFmpeg路径已保存');}
 else if(a==='autofill'){const candidates=S.project.shots.filter(s=>s.videoId);if(!candidates.length){toast('请先为镜头采用视频素材',true);return;}if(S.project.timeline.length){modal(`<h2>重新铺排已采用视频</h2><p class="modal-description">将按分镜顺序重建 ${candidates.length} 个片段，覆盖当前入出点编辑。操作后可以撤销。</p><div class="modal-actions">${button('取消','close-modal')}${button('重建时间线','confirm-autofill','','btn primary')}</div>`);}else autofill();}
 else if(a==='confirm-autofill'){closeModal();autofill();}
 else if(a==='select-clip'){S.clipId=id;S.playing=false;render();}
 else if(a==='toggle-play'){const v=$('#timeline-player');if(!v){toast('选择一个视频片段后播放',true);return;}S.playing=!S.playing;if(S.playing){const c=S.project.timeline.find(c=>c.id===S.clipId);if(v.currentTime>=c.out-.05||v.currentTime<c.in)v.currentTime=c.in;await v.play();}else v.pause();el.innerHTML=icon(S.playing?'pause':'play',20);}
 else if(a==='next-clip')nextClip();else if(a==='prev-clip')nextClip(false,-1);
 else if(a==='move-clip'){const i=S.project.timeline.findIndex(c=>c.id===S.clipId);remember();S.project.timeline=moveItem(S.project.timeline,i,i+Number(el.dataset.dir));changed();render();}
 else if(a==='delete-clip'){remember();S.project.timeline=S.project.timeline.filter(c=>c.id!==S.clipId);S.clipId=null;changed();render();}
 else if(a==='undo'||a==='redo'){const stack=a==='undo'?S.undo:S.redo,dest=a==='undo'?S.redo:S.undo;if(stack.length){dest.push(clone(S.project.timeline));S.project.timeline=stack.pop();S.playing=false;changed();render();}}
 else if(a==='render-movie'){await flush();S.rendering=true;S.renderProgress=0;render();try{const r=await api.renderMovie();if(r)toast('MP4粗剪已导出');}finally{S.rendering=false;render();}}
 }catch(e){toast(e.message,true);if(a==='export-package'){el.disabled=false;el.innerHTML=icon('download',16)+'导出项目 ZIP';}}}
function autofill(){remember();S.project.timeline=S.project.shots.filter(s=>s.videoId).map(s=>({id:uid(),shotId:s.id,mediaId:s.videoId,in:0,out:Math.min(s.duration,media(s.videoId)?.duration||s.duration),muted:true}));S.clipId=S.project.timeline[0]?.id;S.route='edit';changed();render();toast(`已铺排 ${S.project.timeline.length} 个片段，未采用视频的镜头暂未加入`);}
document.addEventListener('click',handleAction);
document.addEventListener('input',e=>{
 const key=e.target.dataset.bind;if(!key)return;const [scope,field]=key.split('.');let value=e.target.type==='checkbox'?e.target.checked:e.target.value;
 if(scope==='shot'){if(field==='duration')value=Math.max(.5,Math.min(120,Number(value)||5));selected()[field]=value;changed();}
 else if(scope==='project'){S.project[field]=value;changed();}
 else if(scope==='connection'){S.editConn[field]=['pollInterval','timeoutSeconds'].includes(field)?Number(value):value;}
});
document.addEventListener('change',e=>{
 const key=e.target.dataset.bind;if(key==='connection.async'||key==='connection.pollMethod'||key==='connection.outputKind')render();
 if(key==='project.ratio'){S.project.width=S.project.ratio==='9:16'?720:1280;S.project.height=S.project.ratio==='9:16'?1280:720;changed();render();}
 if(key?.startsWith('shot.')&&['duration','size','camera'].includes(key.split('.')[1]))render();
 if(e.target.dataset.trim){const c=S.project.timeline.find(c=>c.id===S.clipId),k=e.target.dataset.trim;const v=Number(e.target.value),max=media(c.mediaId)?.duration||120;if(!Number.isFinite(v)||v<0||k==='in'&&v>=c.out||k==='out'&&(v<=c.in||v>max+.01)){toast('入出点超出素材范围',true);render();return;}remember();c[k]=Math.round(v*S.project.fps)/S.project.fps;changed();render();}
 if(e.target.hasAttribute('data-clip-muted')){remember();S.project.timeline.find(c=>c.id===S.clipId).muted=e.target.checked;changed();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){S.search=e.target.value;const caret=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(caret,caret);}});
document.addEventListener('submit',async e=>{if(!['generation-form','asset-form','bind-form','new-project-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,data=new FormData(form);try{
 if(form.id==='generation-form'){if(form.dataset.submitting==='yes')return;const input={clientRequestId:form.dataset.requestId||(form.dataset.requestId=uid()),kind:form.dataset.kind,shotId:form.dataset.shot||null,assetId:form.dataset.asset||null,connectionId:data.get('connection'),prompt:data.get('prompt'),duration:Number(data.get('duration')||5),acknowledged:data.get('acknowledged')==='on'};if(input.connectionId!=='demo'&&!input.acknowledged){toast('请确认本次真实调用可能产生平台费用',true);return;}form.dataset.submitting='yes';form.querySelector('button[type="submit"]').disabled=true;await flush();const t=await api.generate(input);if(!S.project.tasks.some(x=>x.id===t.id))S.project.tasks.unshift(t);closeModal();changed();render();toast('任务已提交，结果将在素材库中保留为候选');}
 if(form.id==='asset-form'){const existing=S.project.assets.find(a=>a.id===form.dataset.id),a={id:form.dataset.id,name:data.get('name').trim(),description:data.get('description').trim(),type:data.get('type'),mediaId:existing?.mediaId||null};if(existing)Object.assign(existing,a);else S.project.assets.push(a);changed();closeModal();render();toast('资产档案已保存');}
 if(form.id==='bind-form'){selected().assetIds=data.getAll('asset');changed();closeModal();render();}
 if(form.id==='new-project-form'){await replaceBootstrap(await api.newProject(data.get('title')));S.route='script';render();toast('新项目已创建');}
 }catch(e){if(form.id==='generation-form'){form.dataset.submitting='no';const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=false;}toast(e.message,true);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();flush().then(()=>toast('项目已保存')).catch(e=>toast(e.message,true));}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-shot],[data-drag-clip]');if(!card)return;S.drag=card.dataset.dragShot?{kind:'shot',id:card.dataset.dragShot}:{kind:'clip',id:card.dataset.dragClip};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',S.drag.id);card.classList.add('dragging');});
document.addEventListener('dragend',()=>{document.querySelectorAll('.dragging').forEach(x=>x.classList.remove('dragging'));S.drag=null;});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drag-shot],[data-drag-clip]'))e.preventDefault();});
document.addEventListener('drop',e=>{const target=e.target.closest('[data-drag-shot],[data-drag-clip]');if(!target||!S.drag)return;e.preventDefault();if(S.drag.kind==='shot'&&target.dataset.dragShot){S.project.shots=moveItem(S.project.shots,S.project.shots.findIndex(s=>s.id===S.drag.id),S.project.shots.findIndex(s=>s.id===target.dataset.dragShot));S.project.shots.forEach((s,i)=>s.code=`SH ${String(i+1).padStart(3,'0')}`);}else if(S.drag.kind==='clip'&&target.dataset.dragClip){remember();S.project.timeline=moveItem(S.project.timeline,S.project.timeline.findIndex(c=>c.id===S.drag.id),S.project.timeline.findIndex(c=>c.id===target.dataset.dragClip));}changed();render();});
api.onEvent(event=>{
 if(event.renderProgress!==undefined){S.renderProgress=event.renderProgress;const el=$('[data-action="render-movie"]');if(el&&S.rendering)el.innerHTML=icon('download',15)+`导出中 ${S.renderProgress}%`;return;}
 const {task,media:m}=event;if(task){const t=S.project?.tasks.find(t=>t.id===task.id);if(t)Object.assign(t,task);else S.project?.tasks.unshift(task);}
 if(m&&!S.project.media.some(x=>x.id===m.id)){S.project.media.push(m);toast((m.demo?'演示素材':'生成素材')+'已入库，请预览后采用');}
 if(task?.status==='failed'||task?.status==='submission_unknown')toast(task.error||'任务需要检查',true);
 changed();if(['media','board'].includes(S.route)&&!S.modal&&!document.activeElement?.matches('input,textarea'))render();
});
try{const data=await api.bootstrap();Object.assign(S,data);S.shotId=S.project.shots[2]?.id||S.project.shots[0]?.id;render();}catch(e){$('#app').innerHTML=`<div class="boot">无法打开工作台<span>${esc(e.message)}</span></div>`;}
